def S_k_11_k(k):
    # Sum for K_{k, 11-k}
    return k * (11 - k) * abs(11 - 2 * k)

def S_mod_k(k):
    # Sum after making the partition of size k a clique
    return k * (11 - k) * abs(10 - k)

