def is_graphic_havel_hakimi(sequence):
    """Checks if a sequence is graphic using the Havel-Hakimi theorem."""
    sequence = sorted([int(d) for d in sequence if d > 0], reverse=True)
    while True:
        if not sequence:
            return True

        n = len(sequence)
        if n == 1 and sequence[0] == 0:
            return True
        if sequence[0] >= n:
            return False # Cannot subtract more than N-1 times

        d1 = sequence.pop(0)

        if d1 > len(sequence):
            return False # Degree too large for remaining vertices

        # Subtract 1 from the next d1 elements
        for i in range(d1):
            sequence[i] -= 1
            if sequence[i] < 0:
                return False # Negative degree

        sequence.sort(reverse=True)
    return False

# The sequence is (5 vertices of degree 10, 6 vertices of degree 5)
degree_sequence = [10] * 5 + [5] * 6
print(f"Degree sequence: {degree_sequence}")
is_graphic = is_graphic_havel_hakimi(degree_sequence)
print(f"Is the sequence graphic? {is_graphic}")
